    if (result4 != 10) {
        printf("Test 4 failed: Expected 10, got %d\n", result4);
        return 1;
    }

    int result5 = get_next_protocol_state(state_table2, 255);  // Last valid index
    if (result5 != 265) {
        printf("Test 5 failed: Expected 265, got %d\n", result5);
        return 1;
    }

    // Test case 3: Different values in state table
    int state_table3[256];
    for (int i = 0; i < 256; i++) {
        state_table3[i] = (i % 10) + 1;  // Cycle through 1-10
    }

    int result6 = get_next_protocol_state(state_table3, 50);
    if (result6 != 1) {  // 50 % 10 = 0, so 0 + 1 = 1
        printf("Test 6 failed: Expected 1, got %d\n", result6);
        return 1;
    }

    int result7 = get_next_protocol_state(state_table3, 53);
    if (result7 != 4) {  // 53 % 10 = 3, so 3 + 1 = 4
        printf("Test 7 failed: Expected 4, got %d\n", result7);
        return 1;
    }

    printf("All functional tests passed!\n");
    return 0;
}

